// Tüm satırları topla
const rows = $input.all().map(i => i.json);

if (rows.length === 0) {
  return [{ json: { status: 'no_rows', message: 'Sentrix bulunamadı' } }];
}

// Sentrix-level bilgi (ilk row'dan, hepsi aynı)
const first = rows[0];
const sentrix_id = first.sentrix_id;
const scan_ref = first.scan_ref;
const chiptype_ref = first.chiptype_ref;

// Chip type kontrolü — şimdilik sadece 126 destekleniyor
const CHIPTYPE_FILES = {
  126: {
    bpm: 'GSACyto_20044998_A1.bpm',
    bpm_concept_ref: 395,
    csv: 'GSACyto_20044998_A1.csv',
    csv_concept_ref: 396,
    egt: '2003.egt',
    egt_concept_ref: 397,
    staging_subdir: 'GSA_Cyto',
    label_prefix: 'GSA_Cyto',
  },
};

if (!CHIPTYPE_FILES[chiptype_ref]) {
  return [{ json: {
    status: 'unsupported_chiptype',
    sentrix_id,
    chiptype_ref,
    message: `chiptype_ref ${chiptype_ref} icin manifest tanimli degil`
  } }];
}

const chip_config = CHIPTYPE_FILES[chiptype_ref];

// idat satırlarını ayıkla (LEFT JOIN sonucu idat null olabilir)
const idats = rows.filter(r => r.idat_uniqueref !== null);

if (idats.length === 0) {
  return [{ json: {
    status: 'no_idats',
    sentrix_id,
    message: 'Bu scan icin idats kaydi yok'
  } }];
}

// Şimdilik: gtc_file_path NULL olanları işle (ilk üretim)
// Rescan mantığını sonraki adımda ekleyeceğiz
const to_process = idats.filter(r => {
  return r.gtc_file_path === null;
});

if (to_process.length === 0) {
  return [{ json: {
    status: 'all_current',
    sentrix_id,
    message: 'Tum positionlar zaten islenmis'
  } }];
}

return [{
  json: {
    status: 'process',
    sentrix_id,
    scan_ref,
    chiptype_ref,
    chip_config,
    total_idats: idats.length,
    to_process_count: to_process.length,
    process_idats: to_process,
    all_idats: idats,
  }
}];

const stdout = $input.first().json.stdout;
let parsed;
try {
  parsed = JSON.parse(stdout);
} catch (e) {
  return [{ json: { 
    status: 'parse_error', 
    raw_stdout: stdout, 
    error: e.message 
  } }];
}

return [{ json: parsed }];

const qcText = $('read_sentrix_qc_ssh').first().json.stdout || '';

const regByPos = {};
for (const line of qcText.split(/\r?\n/)) {
  const parts = line.trim().split(/\s+/);
  if (parts.length < 2) continue;
  const label = parts[0];
  if (!label.endsWith('_1_Swath1_Channel1')) continue;
  const pos = label.split('_')[0];
  const val = parseFloat(parts[1]);
  if (!isNaN(val)) regByPos[pos] = val;
}

const items = $input.all();
const result = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const out = {
    ...j,
    RegistrationScore: regByPos[j.SentrixPosition] ?? null,
  };
  if (i === 0) {
    out._debug_text_length = qcText.length;
    out._debug_reg_positions_count = Object.keys(regByPos).length;
    out._debug_first_pos_value = regByPos['R01C01'];
  }
  result.push({ json: out });
}

return result;

// Concept mapping: xlsx kolon adi -> concept uniqueref
const CONCEPT_MAP = {
  "RegistrationScore": 496,
  "AutosomalCallRate": 497,        // GTC Call Rate concept'i; AutosomalCallRate degerini buraya yaziyoruz
  "NonPolymorphicGRed": 498,
  "NonPolymorphicTRed": 499,
  "HybridizationHighRed": 500,
  "RestorationGreen": 501,
  "NonSpecificBinding4BgndRed": 502,
  "ExtensionTRed": 503,
  "TargetRemovalIRed": 504,
  "ExtensionTGreen": 505,
  "NonSpecificBinding1BgndRed": 506,
  "StringencyStringPMRed": 507,
  "TargetRemovalIGreen": 508,
  "StainingDNPBgndGreen": 509,
  "HybridizationHighGreen": 510,
  "NonPolymorphicCRed": 511,
  "ExtensionCGreen": 512,
  "StainingDNPHighGreen": 513,
  "HybridizationMediumRed": 514,
  "NonSpecificBinding2BgndRed": 515,
  "StringencyStringMMRed": 516,
  "NonPolymorphicAGreen": 517,
  "ExtensionCRed": 518,
  "StainingBiotinHighRed": 519,
  "StainingDNPHighRed": 520,
  "RestorationRed": 521,
  "NonPolymorphicARed": 522,
  "StainingBiotinHighGreen": 523,
  "ExtensionARed": 524,
  "ExtensionAGreen": 525,
  "NonPolymorphicTGreen": 526,
  "StringencyStringMMGreen": 527,
  "StainingBiotinBgndGreen": 528,
  "StainingBiotinBgndRed": 529,
  "NonSpecificBinding4BgndGreen": 530,
  "HybridizationLowGreen": 531,
  "NonPolymorphicCGreen": 532,
  "StringencyStringPMGreen": 533,
  "StainingDNPBgndRed": 534,
  "NonSpecificBinding2BgndGreen": 535,
  "HybridizationMediumGreen": 536,
  "NonPolymorphicGGreen": 537,
  "HybridizationLowRed": 538,
  "NonSpecificBinding3BgndGreen": 539,
  "ExtensionGRed": 540,
  "NonSpecificBinding3BgndRed": 541,
  "NonSpecificBinding1BgndGreen": 542,
  "ExtensionGGreen": 543,
  "LogRDev": 544,
};

// decide_processing'ten gelen idat_uniqueref bilgisi
// process_idats: position -> idat_uniqueref eşleşmesi için
const decision = $('decide_processing').first().json;
const positionToIdatRef = {};
for (const idat of decision.process_idats) {
  positionToIdatRef[idat.position] = idat.idat_uniqueref;
}

// GTC dizini
const gtcDir = $('parse_ssh_output').first().json.gtc_dir;

// QC verisi (24 item)
const qcItems = $input.all().map(i => i.json);

const idatUpdates = [];
const measurementInserts = [];

for (const qc of qcItems) {
  const position = qc.SentrixPosition;
  const idatRef = positionToIdatRef[position];

  // Eğer bu position decide_processing'te işlenmiyorsa atla
  if (!idatRef) continue;

  const sentrix = qc.SentrixBarcode;
  const gtcFilePath = `${gtcDir}/${sentrix}_${position}.gtc`;

  // idats UPDATE satırı
idatUpdates.push({
  uniqueref: parseInt(idatRef),
  gtc_file_path: gtcFilePath,
  estimated_gender: qc.SexEstimate ?? null,
  manifest_bpm_concept_ref: decision.chip_config.bpm_concept_ref,
  manifest_csv_concept_ref: decision.chip_config.csv_concept_ref,
  cluster_file_concept_ref: decision.chip_config.egt_concept_ref,
});

  // Her metric için measurement_idats INSERT satırı
  for (const [qcKey, conceptRef] of Object.entries(CONCEPT_MAP)) {
    const value = qc[qcKey];
    if (value === null || value === undefined) continue;
    const numVal = parseFloat(value);
    if (isNaN(numVal)) continue;

    measurementInserts.push({
      idat_ref: parseInt(idatRef),
      measurement_concept_ref: conceptRef,
      value_as_number: numVal,
    });
  }
}

return [{
  json: {
    idat_updates: idatUpdates,
    measurement_inserts: measurementInserts,
    counts: {
      idat_updates: idatUpdates.length,
      measurement_inserts: measurementInserts.length,
    }
  }
}];

