INSERT INTO measurement_idats (
  idat_ref,
  measurement_concept_ref,
  value_as_number
)
VALUES (
  {{ $json.idat_ref }},
  {{ $json.measurement_concept_ref }},
  {{ $json.value_as_number }}
);
